	ports := freeClientPorts(t, 2)
	clientPort, routePort := ports[0], ports[1]
	options := &server.Options{ServerName: "dont-listen-route-test", Host: "127.0.0.1", Port: clientPort,
		DontListen: true, NoLog: true, NoSigs: true,
